"use client";

import type { ReactElement } from "react";

/**
 * Official wallet brand marks.
 *
 * Every path here is the brand's own vector, transcribed from the source
 * the vendor ships:
 *
 *   MetaMask / Rabby / Backpack / Phantom / Coinbase / Trust / OKX
 *     web3icons branded set (0xa3k5/web3icons, raw-svgs/wallets/branded)
 *   Brave / WalletConnect
 *     simple-icons
 *   Bitget Wallet
 *     bitgetwallet/download -> logo/svg/bitget wallet_logo_512.svg
 *   HOT Wallet
 *     hot-labs.org/images/logo.svg (the mark only, not the wordmark)
 *
 * They are inlined rather than fetched so the picker never shows a broken
 * tile, and so the bundle stays dependency free. Each one is drawn on a
 * 24x24 (or its native) viewBox and scaled by the container, which keeps
 * them crisp at any size.
 */

export type WalletBrand =
  | "metamask"
  | "rabby"
  | "backpack"
  | "phantom"
  | "bitget"
  | "hot"
  | "coinbase"
  | "brave"
  | "trust"
  | "walletconnect"
  | "okx"
  | "tokenpocket";

