/* ------------------------------------------------------------- the table */

const ICONS: Record<WalletBrand, () => ReactElement> = {
  metamask: MetaMaskIcon,
  rabby: RabbyIcon,
  backpack: BackpackIcon,
  phantom: PhantomIcon,
  bitget: BitgetIcon,
  hot: HotIcon,
  coinbase: CoinbaseIcon,
  brave: BraveIcon,
  trust: TrustIcon,
  walletconnect: WalletConnectIcon,
  okx: OkxIcon,
  tokenpocket: TokenPocketIcon,
};

/**
 * Draw the brand mark, or fall back to the two-letter monogram when the
 * wallet is one we have no vector for. The mark fills its container and
 * keeps its own aspect ratio, so it never needs hand tuning.
 */
export function WalletIcon({
  brand,
  monogram,
}: {
  brand?: WalletBrand;
  monogram: string;
}) {
  const Icon = brand ? ICONS[brand] : undefined;
  if (!Icon) {
    return (
      <span className="font-display text-[11px] font-black uppercase tracking-tight text-white">
        {monogram}
      </span>
    );
  }
  return <Icon />;
}
